void Solver::bump_var(int var, double coeff) {
    // Increment activity with the given coefficient.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Lazy rescaling: only when a single variable exceeds the threshold.
    // This avoids the costly full‑scale loop on every call.
    const double OVERFLOW_LIMIT = 1e100;
    if (activity[var] > OVERFLOW_LIMIT) {
        // Scale down all activities and the increment factor.
        const double RESCALE_FACTOR = 1e-100;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= RESCALE_FACTOR;
        }
        var_inc *= RESCALE_FACTOR;
    }

    // Ensure the variable is present in the VSIDS heap and update its key.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
